package ro.leo.visual;
import android.app.*;import android.content.*;import android.content.pm.*;import android.database.Cursor;import android.graphics.*;import android.net.Uri;import android.os.*;import android.provider.ContactsContract;import android.provider.ContactsContract.CommonDataKinds.*;import com.android.vcard.*;import org.json.*;import java.io.*;import java.util.*;

/** Local fixtures, no calls, sent messages, network, or deletion of existing contacts/media. */
public final class FiveAppsTests extends Instrumentation {
 private int checks;private void check(boolean b,String label){if(!b)throw new AssertionError(label);checks++;}
 public void onCreate(Bundle b){start();}
 public void onStart(){Context c=getTargetContext();Bundle result=new Bundle();long raw=-1;File dir=new File(c.getCacheDir(),"five-apps-fixture-"+UUID.randomUUID()),archive=new File(dir,"roundtrip.leo-backup.json"),safety=null;JSONObject original=null;try{dir.mkdirs();
  check(SmsBudget.label(repeat("A",160)).startsWith("1 SMS"),"GSM single segment");check(SmsBudget.label(repeat("A",161)).startsWith("2 SMS"),"GSM multipart");check(SmsBudget.label(repeat("ș",71)).startsWith("2 SMS"),"Unicode multipart");check(SmsBudget.label("🙂").contains("Unicode"),"emoji encoding");check(!ContactBook.valid("abc")&&ContactBook.valid("+1 202 555 0101"),"phone input validation");
  Uri created=c.getContentResolver().insert(ContactsContract.RawContacts.CONTENT_URI,new ContentValues());raw=ContentUris.parseId(created);ContentValues disabled=new ContentValues();disabled.put(ContactsContract.RawContacts.AGGREGATION_MODE,ContactsContract.RawContacts.AGGREGATION_MODE_DISABLED);c.getContentResolver().update(created,disabled,null,null);ContentValues name=new ContentValues();name.put(ContactsContract.Data.RAW_CONTACT_ID,raw);name.put(ContactsContract.Data.MIMETYPE,StructuredName.CONTENT_ITEM_TYPE);name.put(StructuredName.DISPLAY_NAME,"LEO LOCAL FIVE FIXTURE");c.getContentResolver().insert(ContactsContract.Data.CONTENT_URI,name);
  ContactBook.saveNumber(c,raw,-1,"+12025550101",Phone.TYPE_MOBILE);ContactBook.saveNumber(c,raw,-1,"+12025550102",Phone.TYPE_HOME);long contact;try(Cursor r=c.getContentResolver().query(created,new String[]{ContactsContract.RawContacts.CONTACT_ID},null,null,null)){r.moveToFirst();contact=r.getLong(0);}ArrayList<ContactBook.Number> numbers=ContactBook.numbers(c,contact);check(numbers.size()==2,"two numbers belong to one person");ContactBook.saveNumber(c,raw,numbers.get(1).id,"+12025550103",Phone.TYPE_WORK);check(ContactBook.numbers(c,contact).size()==2,"editing one number preserves the other");
  Bitmap icon=Bitmap.createBitmap(40,40,Bitmap.Config.RGB_565);icon.eraseColor(Color.CYAN);ByteArrayOutputStream jpeg=new ByteArrayOutputStream();icon.compress(Bitmap.CompressFormat.JPEG,80,jpeg);icon.recycle();ContactBook.photo(c,raw,jpeg.toByteArray());try(Cursor r=c.getContentResolver().query(ContactsContract.Data.CONTENT_URI,new String[]{Photo.PHOTO},ContactsContract.Data.RAW_CONTACT_ID+"=? AND "+ContactsContract.Data.MIMETYPE+"=?",new String[]{""+raw,Photo.CONTENT_ITEM_TYPE},null)){check(r.moveToFirst()&&r.getBlob(0).length>0,"photo stored in contact provider");}
  VCardComposer composer=new VCardComposer(c,VCardConfig.VCARD_TYPE_V30_GENERIC,"UTF-8");try{check(composer.init(ContactsContract.Contacts._ID+"=?",new String[]{""+contact}),"VCF export initialized");ArrayList<VCardEntry> entries=VCardActivity.parse(composer.createOneEntry().getBytes("UTF-8"));check(entries.size()==1&&entries.get(0).getPhoneList().size()==2,"VCF roundtrip preserves both numbers");}finally{composer.terminate();}
  ProviderInfo provider=c.getPackageManager().getProviderInfo(new ComponentName("ro.leo.keypad","ro.leo.keypad.BackupProvider"),0);check("ro.leo.keypad.MANAGE_BACKUP".equals(provider.readPermission),"dictionary provider protected");check(c.getPackageManager().getPermissionInfo("ro.leo.keypad.MANAGE_BACKUP",0).protectionLevel==PermissionInfo.PROTECTION_SIGNATURE,"signature-only dictionary permission");
  original=BackupEngine.snapshot(c);BackupEngine.validate(c,original);BackupEngine.write(archive,BackupEngine.archive(original));JSONObject read=BackupEngine.read(c,archive);check(read.getJSONObject("dictionary").getString("words").equals(original.getJSONObject("dictionary").getString("words")),"dictionary roundtrip");
  JSONObject invalid=new JSONObject(original.toString());invalid.getJSONObject("preferences").getJSONObject("appearance").put("email-password",new JSONObject().put("type","string").put("value","fixture"));boolean rejected=false;try{BackupEngine.validate(c,invalid);}catch(Exception expected){rejected=true;}check(rejected,"unknown preference rejected before mutation");JSONObject corrupt=new JSONObject(new String(BackupEngine.bytes(archive,BackupEngine.MAX),"UTF-8"));corrupt.put("sha256","00");BackupEngine.write(archive,corrupt.toString().getBytes("UTF-8"));rejected=false;try{BackupEngine.read(c,archive);}catch(Exception expected){rejected=true;}check(rejected,"corrupt checksum rejected");
  JSONObject fixture=new JSONObject(original.toString());fixture.put("notes",new JSONArray().put(new JSONObject().put("id","leo-five-local-note").put("body","Notiță locală de probă")));fixture.getJSONObject("preferences").getJSONObject("appearance").put("theme",new JSONObject().put("type","int").put("value",3));safety=BackupEngine.restore(c,fixture);check(safety.isFile()&&!BackupEngine.pending(c).exists(),"restore creates safety copy and clears journal");check(c.getSharedPreferences("appearance",0).getInt("theme",-1)==3,"restored theme applied");JSONArray restored=new JSONArray(new String(BackupEngine.bytes(new File(c.getFilesDir(),"notes.json"),4*1024*1024),"UTF-8"));check(restored.getJSONObject(0).getString("id").equals("leo-five-local-note"),"restored notes applied");
  check(AppCatalog.NAMES.length==28&&IconArt.COLORS.length==28&&AppCatalog.NAMES[27].equals("Backup Leo"),"backup appended with stable app ID");result.putString("result","PASS "+checks+" local contacts, VCF, SMS, backup and catalog checks");
 }catch(Throwable e){result.putString("error",android.util.Log.getStackTraceString(e));}finally{if(original!=null)try{BackupEngine.apply(c,original);new android.util.AtomicFile(BackupEngine.pending(c)).delete();}catch(Exception e){result.putString("restore_error",e.getClass().getSimpleName());}if(raw>=0)c.getContentResolver().delete(ContentUris.withAppendedId(ContactsContract.RawContacts.CONTENT_URI,raw),null,null);if(safety!=null)safety.delete();archive.delete();dir.delete();}finish(result.containsKey("error")||result.containsKey("restore_error")?Activity.RESULT_CANCELED:Activity.RESULT_OK,result);}
 private String repeat(String value,int n){StringBuilder s=new StringBuilder();for(int i=0;i<n;i++)s.append(value);return s.toString();}
}
